# %% [markdown]
# # Core: Traces and responses
#
# - `Traces`: Raw fluorescence trace of each ROI for each presentation.
# - `PreprocessParams`: Parameters for trace preprocessing (e.g. detrending, normalization).
# - `PreprocessTraces`: Preprocessed traces, computed from `Traces` with the chosen parameters.
# - `Snippets`: Preprocessed traces cut into repetitions of the stimulus using the trigger times.
# - `Averages`: Average over the repetitions (snippets), resampled to a common time grid.

# %%
Traces().populate(processes=20, display_progress=True)
Traces()

# %%
PreprocessParams().add_default(skip_duplicates=True)
PreprocessParams()

# %%
PreprocessTraces().populate(processes=20, display_progress=True)
PreprocessTraces()

# %%
plot_if_data(PreprocessTraces(), key=None)

# %%
Snippets().populate(processes=20, display_progress=True)
Snippets()

# %%
plot_if_data(Snippets(), key=None)

# %%
Averages().populate(processes=20, display_progress=True)
Averages()

# %%
plot_if_data(Averages(), method='plot', restriction={"stim_name": "gChirp"})
